-- Authenticated GPS tracker provisioning, credential rotation, and revocation RPCs.
-- Credentials are generated by the Worker; only SHA-256 hashes are stored.

CREATE OR REPLACE FUNCTION public.darb_api_enroll_gps_tracker(
  p_vehicle_id uuid,
  p_label text,
  p_protocol text,
  p_imei text,
  p_model text,
  p_timezone_offset_minutes integer,
  p_credential_hash text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_device private.darb_tracking_devices;
  v_protocol text := coalesce(p_protocol, 'json');
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  IF p_vehicle_id IS NULL OR p_credential_hash IS NULL OR p_credential_hash !~ '^[0-9a-f]{64}$'
     OR v_protocol NOT IN ('json','gt06','nmea')
     OR (p_label IS NOT NULL AND length(trim(p_label)) > 100)
     OR (p_model IS NOT NULL AND length(trim(p_model)) > 80)
     OR (p_imei IS NOT NULL AND p_imei !~ '^[0-9]{8,20}$')
     OR (p_timezone_offset_minutes IS NOT NULL AND p_timezone_offset_minutes NOT BETWEEN -840 AND 840)
     OR (v_protocol = 'gt06' AND (p_imei IS NULL OR p_timezone_offset_minutes IS NULL))
     OR (v_protocol = 'nmea' AND p_imei IS NULL) THEN
    RAISE EXCEPTION 'Invalid tracker profile' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.vehicles v
    JOIN public.vehicle_members vm ON vm.vehicle_id = v.id
    WHERE v.id = p_vehicle_id AND v.status = 'active'
      AND vm.user_id = v_user AND vm.status = 'active' AND vm.role IN ('owner','manager')
  ) THEN
    RAISE EXCEPTION 'Vehicle not found or permission denied' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO private.darb_tracking_devices
    (vehicle_id, created_by, label, credential_hash, protocol, imei, model, timezone_offset_minutes)
  VALUES
    (p_vehicle_id, v_user, nullif(trim(coalesce(p_label,'')),''), p_credential_hash, v_protocol,
     p_imei, nullif(trim(coalesce(p_model,'')),''), p_timezone_offset_minutes)
  RETURNING * INTO v_device;

  RETURN jsonb_build_object('id', v_device.id, 'vehicle_id', v_device.vehicle_id,
    'label', v_device.label, 'status', v_device.status, 'created_at', v_device.created_at,
    'protocol', v_device.protocol, 'imei', v_device.imei, 'model', v_device.model,
    'timezone_offset_minutes', v_device.timezone_offset_minutes);
END;
$$;

CREATE OR REPLACE FUNCTION public.darb_api_rotate_gps_credential(p_device_id uuid, p_credential_hash text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_device private.darb_tracking_devices;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  IF p_device_id IS NULL OR p_credential_hash IS NULL OR p_credential_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Invalid credential rotation request' USING ERRCODE = '22023';
  END IF;
  UPDATE private.darb_tracking_devices d
    SET credential_hash = p_credential_hash
  WHERE d.id = p_device_id AND d.status = 'active'
    AND EXISTS (SELECT 1 FROM public.vehicle_members vm
      WHERE vm.vehicle_id = d.vehicle_id AND vm.user_id = v_user
        AND vm.status = 'active' AND vm.role IN ('owner','manager'))
  RETURNING * INTO v_device;
  IF v_device.id IS NULL THEN RAISE EXCEPTION 'Device not found or permission denied' USING ERRCODE = 'P0002'; END IF;
  RETURN jsonb_build_object('deviceId', v_device.id, 'vehicleId', v_device.vehicle_id, 'protocol', v_device.protocol);
END;
$$;

CREATE OR REPLACE FUNCTION public.darb_api_revoke_gps_tracker(p_device_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user uuid := auth.uid();
  v_device_id uuid;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF;
  UPDATE private.darb_tracking_devices d
    SET status = 'revoked'
  WHERE d.id = p_device_id AND d.status = 'active'
    AND EXISTS (SELECT 1 FROM public.vehicle_members vm
      WHERE vm.vehicle_id = d.vehicle_id AND vm.user_id = v_user
        AND vm.status = 'active' AND vm.role IN ('owner','manager'))
  RETURNING d.id INTO v_device_id;
  IF v_device_id IS NULL THEN RAISE EXCEPTION 'Device not found or permission denied' USING ERRCODE = 'P0002'; END IF;
  RETURN jsonb_build_object('revoked', true, 'deviceId', v_device_id);
END;
$$;

REVOKE ALL ON FUNCTION public.darb_api_enroll_gps_tracker(uuid, text, text, text, text, integer, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.darb_api_rotate_gps_credential(uuid, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.darb_api_revoke_gps_tracker(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.darb_api_enroll_gps_tracker(uuid, text, text, text, text, integer, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.darb_api_rotate_gps_credential(uuid, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.darb_api_revoke_gps_tracker(uuid) TO authenticated;
